module.exports = function (RED) {
    "use strict";

    function EventSourceNode(n) {
        RED.nodes.createNode(this, n);
        let node = this;

        this.location = n.location;
        this.sensorId = n.sensorId;
        this.deviceName = n.deviceName;
        this.deviceType = n.deviceType;
        this.datasourceType = n.datasourceType;

        let newMsg = {};
        let steps = 1;
        Object.assign(newMsg, {steps: steps});

        // 在节点初始化时自动执行一次
        setImmediate(function () {
            node.emit("input", {});
        });

        this.on("input", function (msg, send, done) {
            msg = msg || {};
            msg.step = 1;
            msg.type = node.type;
            msg.location = node.location;
            msg.sensorId = node.sensorId;

            // 使用与前端匹配的字段名输出
            if (node.deviceName) {
                msg.deviceName = node.deviceName;
            }
            if (node.deviceType) {
                msg.deviceType = node.deviceType;
            }
            msg.datasourceType = node.datasourceType;

            let nodeId = node.id;
            newMsg[nodeId] = msg;
            send(newMsg);
            done();
        });
    }

    RED.nodes.registerType("EventSource", EventSourceNode);
}